var state = TryMap(raw.Code);
log.Telemetry(device.Id, firmware, raw.Code,
              mappingRevision, state, raw.Value, raw.Unit);
if (state == DeviceState.Unknown)
    alert.MarkUnclassified(raw.Code);

public sealed record DeviceTelemetry(
    string DeviceId, string Firmware, DateTimeOffset ObservedAt,
    string RawStatusCode, string MappingRevision,
    string NormalizedState, string? Unit, double? Value);
